{"command": "cat > /tmp/h3.py <<'PY'
import subprocess,os,pty,select,time
env=dict(os.environ); env['TERM']='xterm'; env['COLUMNS']='80'
EX='/workspace/executable'
def run(args, out_tty=True, err_tty=True, in_tty=True, stdin=b'', timeout=8):
    fds={}
    mfd=None
    if out_tty or err_tty:
        mfd,sfd=pty.openpty()
        so = sfd if out_tty else subprocess.PIPE
        se = sfd if err_tty else subprocess.PIPE
    else:
        so,se = subprocess.PIPE, subprocess.PIPE
    si = sfd if (in_tty and mfd is not None) else subprocess.PIPE
    p=subprocess.Popen([EX]+args,stdout=so,stderr=se,stdin=si,env=env)
    if mfd is not None: os.close(sfd)
    if not in_tty and stdin: pass
    ptbuf=b''
    if mfd is not None:
        if in_tty and stdin:
            time.sleep(0.05)
            try: os.write(mfd,stdin)
            except OSError: pass
    pipe_out=b''; pipe_err=b''
    start=time.time()
    while time.time()-start<timeout:
        r=[]
        if mfd is not None: r.append(mfd)
        if not out_tty: r.append(p.stdout)
        if not err_tty: r.append(p.stderr)
        rl,_,_=select.select(r,[],[],0.05)
        if mfd is not None and mfd in rl:
            try: d=os.read(mfd,65536)
            except OSError: break
            if not d: break
            ptbuf+=d
        if not out_tty and p.stdout in rl: pipe_out+=p.stdout.read(65536)
        if not err_tty and p.stderr in rl: pipe_err+=p.stderr.read(65536)
        if p.poll() is not None: break
    p.wait()
    if not out_tty:
        pipe_out+=p.stdout.read()
    if not err_tty:
        pipe_err+=p.stderr.read()
    if mfd is not None:
        try: os.close(mfd)
        except: pass
    return p.returncode, pipe_out, pipe_err, ptbuf
PY
