{"command": "cd /workspace && cat > request.go <<'GOEOF'
package main

import (
	"encoding/json"
	"fmt"
	"net/url"
	"os"
	"sort"
	"strings"
)

var methods = map[string]bool{
	"GET": true, "POST": true, "PUT": true, "DELETE": true,
	"PATCH": true, "HEAD": true, "OPTIONS": true, "TRACE": true,
}

// dataOpts are curl options that make curlie consider the request to carry a
// body (they suppress the implicit `-d @-`).
var dataOpts = map[string]bool{
	"-d": true, "--data": true, "--data-raw": true,
}

type item struct {
	bare   bool
	header bool
	val    string
}

type request struct {
	args   []string // passthrough curl arguments, in the order given
	method string
	url    string
	urlRaw string
	urlSet bool

	items    []item
	data     map[string]interface{}
	dataSet  bool
	query    [][2]string
	hasData  bool
	hasCT    bool
	hasAcc   bool
	echoData string

	pretty  bool
	showCmd bool
	helpSet bool
	helpCat string
	verbose bool
}

func isMethod(s string) bool { return methods[strings.ToUpper(s)] }

func (r *request) noteValue(opt, val string) {
	switch opt {
	case "-d", "--data", "--data-raw":
		r.dataSet = true
	case "-H", "--header":
		r.noteHeader(val)
	}
}

func (r *request) noteHeader(val string) {
	i := strings.Index(val, ":")
	if i < 0 {
		return
	}
	name := strings.ToLower(strings.TrimSpace(val[:i]))
	switch name {
	case "content-type":
		r.hasCT = true
	case "accept":
		r.hasAcc = true
	}
}

func (r *request) setURL(raw string) {
	s := strings.TrimPrefix(raw, "//")
	r.urlRaw = s
	r.url = normalizeCurlURL(s)
	r.urlSet = true
}

// normalizeCurlURL turns a curlie URL argument into the string that is handed
// to curl.  It reproduces the (quirky) behaviour observed in the original.
func normalizeCurlURL(s string) string {
	if strings.HasPrefix(s, "http") && !strings.HasPrefix(s, "http://") && !strings.HasPrefix(s, "https://") {
		if i := strings.Index(s, ":"); i >= 0 {
			s = strings.ToLower(s[:i+1]) + s[i+1:]
		}
	}
	if strings.HasPrefix(s, "http://") || strings.HasPrefix(s, "https://") {
		return s
	}
	if i := strings.Index(s, "://"); i > 0 {
		return s
	}
	full := "http://" + s
	p, err := url.Parse(full)
	if err != nil {
		fmt.Print(err)
		return full
	}
	return rebuildURL(p)
}

func rebuildURL(p *url.URL) string {
	if p.Host == "" {
		if p.Path == "" {
			return p.String()
		}
		res := p.Path
		if p.ForceQuery || p.RawQuery != "" {
			res += "?" + p.RawQuery
		}
		if p.Fragment != "" {
			res += "#" + p.Fragment
		}
		return res
	}
	host := p.Host
	if host[0] == ':' {
		port := ""
		if i := strings.Index(host, ":"); i >= 0 {
			port = host[i+1:]
		}
		host = "localhost"
		if port != "" {
			host += ":" + port
		}
	}
	res := host + p.Path
	if p.ForceQuery || p.RawQuery != "" {
		res += "?" + p.RawQuery
	}
	if p.Fragment != "" {
		res += "#" + p.Fragment
	}
	return res
}

// displayURL is what curlie echoes on stderr before performing the request.
func displayURL(s string) string {
	if strings.HasPrefix(s, "http") {
		return s
	}
	return "http://" + s
}

func (r *request) addItem(a string) {
	// find the first separator
	pos := -1
	for i := 0; i < len(a); i++ {
		if a[i] == ':' || a[i] == '=' {
			pos = i
			break
		}
	}
	if pos < 0 {
		r.items = append(r.items, item{bare: true, val: a})
		return
	}
	sep := a[pos]
	kind := ""
	switch sep {
	case ':':
		if pos+1 < len(a) && a[pos+1] == '=' {
			kind = "json"
		} else {
			kind = "header"
		}
	case '=':
		if pos+1 < len(a) && a[pos+1] == '=' {
			kind = "query"
		} else {
			kind = "data"
		}
	}
	switch kind {
	case "header":
		r.items = append(r.items, item{header: true, val: a})
		r.noteHeader(a)
	case "query":
		r.query = append(r.query, [2]string{a[:pos], a[pos+2:]})
	case "data":
		r.setData(a[:pos], a[pos+1:])
	case "json":
		var v interface{}
		if err := json.Unmarshal([]byte(a[pos+2:]), &v); err != nil {
			v = nil
		}
		r.setData(a[:pos], v)
	}
}

func (r *request) setData(key string, val interface{}) {
	if r.data == nil {
		r.data = map[string]interface{}{}
	}
	r.data[key] = val
	r.hasData = true
}

// dataJSON renders the JSON body built from request items.
func (r *request) dataJSON() (string, bool) {
	if len(r.data) == 0 {
		return "", false
	}
	b, err := json.Marshal(r.data)
	if err != nil {
		return "", false
	}
	return string(b), true
}

// querySuffix appends the `==` request items to the URL.
func (r *request) querySuffix() string {
	if len(r.query) == 0 {
		return ""
	}
	parts := make([]string, 0, len(r.query))
	for _, q := range r.query {
		parts = append(parts, url.QueryEscape(q[0])+"="+url.QueryEscape(q[1]))
	}
	return strings.Join(parts, "&")
}

// parse walks over the command line arguments and classifies them.
func parse(args []string) *request {
	r := &request{data: map[string]interface{}{}}
	noMore := false
	for i := 0; i < len(args); {
		a := args[i]
		i++
		if !noMore && len(a) > 1 && a[0] == '-' {
			if a == "--" {
				noMore = true
				continue
			}
			if a[1] == '-' {
				name := a
				switch name {
				case "--curl":
					r.showCmd = true
					continue
				case "--pretty":
					r.pretty = true
					continue
				case "--include", "--form":
					continue
				}
				r.args = append(r.args, name)
				if valueOpts[name] {
					if i < len(args) {
						r.args = append(r.args, args[i])
						r.noteValue(name, args[i])
						i++
					} else {
						r.noteValue(name, "")
					}
				} else {
					r.noteValue(name, "")
				}
				continue
