	args   []string // passthrough curl arguments, in the order given
	method string
	url    string
	urlRaw string
	urlSet bool

	items    []item
	data     map[string]interface{}
	dataSet  bool
	query    [][2]string
	hasData  bool
	hasCT    bool
	hasAcc   bool
	echoData string

	pretty  bool
	showCmd bool
	helpSet bool
	helpCat string
	verbose bool
}

func isMethod(s string) bool { return methods[strings.ToUpper(s)] }

func (r *request) noteValue(opt, val string) {
	switch opt {
	case "-d", "--data", "--data-raw":
		r.dataSet = true
	case "-H", "--header":
		r.noteHeader(val)
	}
}

func (r *request) noteHeader(val string) {
	i := strings.Index(val, ":")
	if i < 0 {
		return
	}
	name := strings.ToLower(strings.TrimSpace(val[:i]))
	switch name {
	case "content-type":
		r.hasCT = true
	case "accept":
		r.hasAcc = true
	}
}

func (r *request) setURL(raw string) {
	s := strings.TrimPrefix(raw, "//")
	r.urlRaw = s
	r.url = normalizeCurlURL(s)
	r.urlSet = true
}

// normalizeCurlURL turns a curlie URL argument into the string that is handed
// to curl.  It reproduces the (quirky) behaviour observed in the original.
func normalizeCurlURL(s string) string {
	if strings.HasPrefix(s, "http") && !strings.HasPrefix(s, "http://") && !strings.HasPrefix(s, "https://") {
		if i := strings.Index(s, ":"); i >= 0 {
			s = strings.ToLower(s[:i+1]) + s[i+1:]
		}
	}
	if strings.HasPrefix(s, "http://") || strings.HasPrefix(s, "https://") {
		return s
	}
	if i := strings.Index(s, "://"); i > 0 {
		return s
	}
	full := "http://" + s
	p, err := url.Parse(full)
	if err != nil {
		fmt.Print(err)
		return full
	}
	return rebuildURL(p)
}

func rebuildURL(p *url.URL) string {
	if p.Host == "" {
		if p.Path == "" {
			return p.String()
		}
		res := p.Path
		if p.ForceQuery || p.RawQuery != "" {
			res += "?" + p.RawQuery
		}
		if p.Fragment != "" {
			res += "#" + p.Fragment
		}
		return res
	}
	host := p.Host
	if host[0] == ':' {
		port := ""
		if i := strings.Index(host, ":"); i >= 0 {
			port = host[i+1:]
		}
		host = "localhost"
		if port != "" {
			host += ":" + port
		}
	}
	res := host + p.Path
	if p.ForceQuery || p.RawQuery != "" {
		res += "?" + p.RawQuery
	}
	if p.Fragment != "" {
		res += "#" + p.Fragment
	}
	return res
}

// displayURL is what curlie echoes on stderr before performing the request.
func displayURL(s string) string {
	if strings.HasPrefix(s, "http") {
		return s
	}
	return "http://" + s
}

func (r *request) addItem(a string) {
	// find the first separator
	pos := -1
	for i := 0; i < len(a); i++ {
		if a[i] == ':' || a[i] == '=' {
			pos = i
			break
		}
	}
	if pos < 0 {
		r.items = append(r.items, item{bare: true, val: a})
		return
	}
	sep := a[pos]
	kind := ""
	switch sep {
	case ':':
		if pos+1 < len(a) && a[pos+1] == '=' {
			kind = "json"
		} else {
			kind = "header"
		}
	case '=':
		if pos+1 < len(a) && a[pos+1] == '=' {
			kind = "query"
		} else {
			kind = "data"
		}
	}
	switch kind {
	case "header":
		r.items = append(r.items, item{header: true, val: a})
		r.noteHeader(a)
	case "query":
		r.query = append(r.query, [2]string{a[:pos], a[pos+2:]})
	case "data":
		r.setData(a[:pos], a[pos+1:])
	case "json":
		var v interface{}
		if err := json.Unmarshal([]byte(a[pos+2:]), &v); err != nil {
			v = nil
		}
		r.setData(a[:pos], v)
	}
}

func (r *request) setData(key string, val interface{}) {
	if r.data == nil {
		r.data = map[string]interface{}{}
	}
	r.data[key] = val
	r.hasData = true
}

// dataJSON renders the JSON body built from request items.
func (r *request) dataJSON() (string, bool) {
	if len(r.data) == 0 {
		return "", false
	}
	b, err := json.Marshal(r.data)
	if err != nil {
		return "", false
	}
	return string(b), true
}

// querySuffix appends the `==` request items to the URL.
func (r *request) querySuffix() string {
	if len(r.query) == 0 {
		return ""
	}
	parts := make([]string, 0, len(r.query))
	for _, q := range r.query {
		parts = append(parts, url.QueryEscape(q[0])+"="+url.QueryEscape(q[1]))
	}
	return strings.Join(parts, "&")
}

// parse walks over the command line arguments and classifies them.
func parse(args []string) *request {
	r := &request{data: map[string]interface{}{}}
	noMore := false
	for i := 0; i < len(args); {
		a := args[i]
		i++
		if !noMore && len(a) > 1 && a[0] == '-' {
			if a == "--" {
				noMore = true
				continue
			}
			if a[1] == '-' {
				name := a
				switch name {
				case "--curl":
					r.showCmd = true
					continue
				case "--pretty":
					r.pretty = true
					continue
				case "--include", "--form":
					continue
				}
				r.args = append(r.args, name)
				if valueOpts[name] {
					if i < len(args) {
						r.args = append(r.args, args[i])
						r.noteValue(name, args[i])
						i++
					} else {
						r.noteValue(name, "")
					}
				} else {
					r.noteValue(name, "")
				}
				continue
			}
			// cluster of short options
			rest := a[1:]
			for j := 0; j < len(rest); j++ {
				c := string(rest[j])
				name := "-" + c
				switch c {
				case "i", "F":
					continue
				}
				if valueOpts[name] {
					if j+1 < len(rest) {
						val := rest[j+1:]
						r.args = append(r.args, name, val)
						r.noteValue(name, val)
					} else {
						r.args = append(r.args, name)
						if i < len(args) {
							r.args = append(r.args, args[i])
							r.noteValue(name, args[i])
							i++
						} else {
							r.noteValue(name, "")
						}
					}
					j = len(rest)
					break
				}
				r.args = append(r.args, name)
				r.noteValue(name, "")
			}
			continue
		}
		// a plain argument
		if !r.urlSet {
			if r.method == "" && isMethod(a) {
				r.method = strings.ToUpper(a)
				continue
			}
			r.setURL(a)
			continue
		}
		r.addItem(a)
	}
	return r
}

// buildArgs produces the argument list that is passed on to curl.
func (r *request) buildArgs() []string {
	var out []string
	out = append(out, r.args...)
	switch {
	case r.method == "":
	case r.method == "HEAD":
		out = append(out, "-I")
	default:
		out = append(out, "-X", r.method)
	}
	for _, it := range r.items {
		if it.header {
			out = append(out, "-H", it.val)
		} else {
			out = append(out, it.val)
		}
	}
	if body, ok := r.dataJSON(); ok {
		out = append(out, "-d", body)
	}
	u := r.url
	if s := r.querySuffix(); s != "" {
		if strings.Contains(u, "?") {
			u += "&" + s
		} else {
			u += "?" + s
		}
	}
	out = append(out, u)
	out = append(out, "-s", "-S")
	if !r.dataSet && !isATTY(os.Stdin) {
		out = append(out, "-d@-")
	}
	if _, ok := r.dataJSON(); ok || r.dataSet || !isATTY(os.Stdin) {
		if !r.hasCT {
			out = append(out, "-H", "Content-Type: application/json")
		}
	}
	if !r.hasAcc {
		out = append(out, "-H", "Accept: application/json, */*")
	}
	return out
}

// renderArgs renders the command line the way curlie prints it with --curl.
func renderArgs(args []string) string {
	parts := make([]string, 0, len(args))
	for _, a := range args {
		parts = append(parts, shellQuote(a))
	}
	return strings.Join(parts, " ")
}

func shellQuote(s string) string {
	if !strings.Contains(s, " ") {
		return s
	}
	return "\"" + strings.ReplaceAll(s, "\"", "\\\"") + "\""
}

// sortedKeys is only used for deterministic tests of the data map.
func sortedKeys(m map[string]interface{}) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}
