func parse(args []string) (*request, error) {
    r := &request{data: map[string]interface{}{}}
    noMore := false
    i := 0
    for i < len(args) {
        a := args[i]
        i++
        if !noMore && len(a) > 1 && a[0] == '-' {
            if a == "--" { noMore = true; continue }
            // option
            if strings.HasPrefix(a, "--") {
                name := a   // hmm: the whole "--name" (no = splitting)
                // curlie-specific
                switch name {
                case "--curl": r.showCmd = true; continue
                case "--pretty": r.pretty = true; continue
                case "--include": continue   // removed
                case "--form": continue      // removed
                }
                r.args = append(r.args, name)
                if valueOpts[name] {
                    if i < len(args) { r.args = append(r.args, args[i]); noteValue(name, args[i]); i++ }
                } else { noteFlag(name) }
                continue
            }
            // short cluster
            rest := a[1:]
            for j := 0; j < len(rest); j++ {
                c := rest[j:j+1]
                name := "-" + c
                switch c {
                case "i": continue   // removed
                case "F": continue   // removed
                }
                if valueOpts[name] {
                    // the value is the rest of the cluster, or the next arg
                    if j+1 < len(rest) {
                        val := rest[j+1:]
                        r.args = append(r.args, name, val)
                        noteValue(name, val)
                        j = len(rest)
                    } else {
                        r.args = append(r.args, name)
                        if i < len(args) { r.args = append(r.args, args[i]); noteValue(name, args[i]); i++ }
                    }
                    break
                }
                r.args = append(r.args, name)
                noteFlag(name)
            }
            continue
        }
        // non-option arg
        if a == "-" {
            // hmm: "-" is not an option → a non-option arg
        }
        if !r.urlSet {
            if r.method == "" && isMethod(a) { r.method = strings.ToUpper(a); continue }
            // URL
            r.setURL(a)
            continue
        }
        r.addItem(a)
    }
    return r, nil
}
```

