func rebuildURL(p *url.URL) string {
    if p.Host == "" {
        if p.Path == "" {
            return p.String()
        }
        // no authority: just the path (+query/fragment)
        return p.Path + queryPart(p) + fragPart(p)
    }
    host := p.Host
    if host[0] == ':' {
        i := strings.Index(host, ":")
        port := host[i+1:]
        host = "localhost"
