package main

import (
	"io"
	"strings"
)

const (
	escReset   = "\x1b[0m"
	escWhite   = "\x1b[37m"
	escBlue    = "\x1b[34m"
	escCyan    = "\x1b[36m"
	escMagenta = "\x1b[35m"
	escGray    = "\x1b[90m"
	escRed     = "\x1b[31m"
	escYellow  = "\x1b[33m"
)

func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

func isStruct(c byte) bool {
	switch c {
	case '{', '}', '[', ']', ',', ':':
		return true
	}
	return false
}

// jsonPrinter pretty prints a JSON stream on the fly.
type jsonPrinter struct {
	w       io.Writer
	colors  bool
	decided bool
	pretty  bool
	depth   int
	colon   bool // previous token was ":"
	inStr   bool
	tok     []byte
}

func (p *jsonPrinter) raw(s string) { io.WriteString(p.w, s) }

func (p *jsonPrinter) col(code, text string) {
	if p.colors && code != "" {
