package main

import (
	"io"
	"strings"
)

var statusRe = "HTTP/"

// respFilter copies curl's stderr to the terminal, colouring the interesting
// parts and dropping the rest.
type respFilter struct {
	w        io.Writer
	colors   bool
	verbose  bool
	echoData string

	pending  string
	havePend bool
	status   int
	buf      []byte
}

func (f *respFilter) raw(s string) { io.WriteString(f.w, s) }

func (f *respFilter) col(code, text string) {
	if f.colors {
		io.WriteString(f.w, code)
	}
	io.WriteString(f.w, text)
}

func (f *respFilter) write(data []byte) error {
	for _, c := range data {
		if c == '\n' {
			f.line(string(f.buf))
			f.buf = f.buf[:0]
			continue
		}
		f.buf = append(f.buf, c)
	}
	return nil
}

func (f *respFilter) flushLine() {
	if len(f.buf) > 0 {
		f.line(string(f.buf))
		f.buf = f.buf[:0]
	}
}

func isBlank(s string) bool { return s == "" || s == "\r" }

func isDataLine(s string) bool {
	return strings.HasPrefix(s, "{ ") || strings.HasPrefix(s, "} ")
}

// flushPending writes out a blank line that was held back while waiting to
// know whether the response was complete.
func (f *respFilter) flushPending() {
	if !f.havePend {
		return
	}
	f.raw(f.pending)
	io.WriteString(f.w, "\n")
	f.pending = ""
	f.havePend = false
}

func (f *respFilter) dropPending() {
	f.pending = ""
	f.havePend = false
}

func (f *respFilter) line(s string) {
