// parseStatusLine recognises "HTTP/1.1 200 OK" style lines.
func parseStatusLine(s string) (ver, code, reason string, ok bool) {
	if !strings.HasPrefix(s, "HTTP/") {
		return "", "", "", false
	}
	rest := s[5:]
	// version: digits and dots
	i := 0
	for i < len(rest) && (rest[i] >= '0' && rest[i] <= '9' || rest[i] == '.') {
		i++
	}
	if i == 0 || i >= len(rest) || rest[i] != ' ' {
		return "", "", "", false
	}
	ver = rest[:i]
	j := i
	for j < len(rest) && rest[j] == ' ' {
		j++
	}
	k := j
	for k < len(rest) && rest[k] >= '0' && rest[k] <= '9' {
		k++
	}
	if k-j != 3 {
		return "", "", "", false
	}
	code = rest[j:k]
	if k >= len(rest) || rest[k] != ' ' {
		return "", "", "", false
	}
	reason = rest[k:]
	if reason == "" {
		return "", "", "", false
	}
	return ver, code, reason, true
}

// parseRequestLine recognises "GET /path HTTP/1.1" style lines.
func parseRequestLine(s string) (method, path, ver string, ok bool) {
	i := strings.IndexByte(s, ' ')
	if i < 0 {
		return "", "", "", false
	}
	j := strings.LastIndexByte(s, ' ')
	if j <= i {
		return "", "", "", false
	}
	rest := s[j+1:]
	if !strings.HasPrefix(rest, "HTTP/") || j+5 >= len(s) {
		return "", "", "", false
	}
	ver = rest[5:]
	if ver == "" {
		return "", "", "", false
	}
	if !isVersion(ver) {
		return "", "", "", false
	}
	return s[:i], s[i+1 : j], ver, true
}

func isVersion(s string) bool {
	dot := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '.' {
			dot = true
			continue
		}
		if c < '0' || c > '9' {
			return false
		}
	}
	return dot
}

func atoi(s string) int {
	n := 0
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return n
		}
		n = n*10 + int(s[i]-'0')
	}
	return n
}
