package main

import (
	"io"
	"strings"
)

const (
	escReset   = "\x1b[0m"
	escWhite   = "\x1b[37m"
	escBlue    = "\x1b[34m"
	escCyan    = "\x1b[36m"
	escMagenta = "\x1b[35m"
	escGray    = "\x1b[90m"
	escRed     = "\x1b[31m"
	escYellow  = "\x1b[33m"
)

func isSpace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

func isStruct(c byte) bool {
	switch c {
	case '{', '}', '[', ']', ',', ':':
		return true
	}
	return false
}

// jsonPrinter pretty prints a JSON stream on the fly.
type jsonPrinter struct {
	w       io.Writer
	colors  bool
	decided bool
	pretty  bool
	depth   int
	colon   bool // previous token was ":"
	inStr   bool
	tok     []byte
}

func (p *jsonPrinter) raw(s string) { io.WriteString(p.w, s) }

func (p *jsonPrinter) col(code, text string) {
	if p.colors && code != "" {
		io.WriteString(p.w, code)
	}
	io.WriteString(p.w, text)
}

func (p *jsonPrinter) indent() {
	io.WriteString(p.w, strings.Repeat("    ", p.depth))
}

func (p *jsonPrinter) newline() {
	io.WriteString(p.w, "\n")
	p.indent()
}

func (p *jsonPrinter) write(data []byte) error {
	if !p.decided {
		if len(data) == 0 {
			return nil
		}
		p.pretty = data[0] == '{' || data[0] == '['
		p.decided = true
		if !p.pretty {
			_, err := p.w.Write(data)
			return err
		}
	} else if !p.pretty {
		_, err := p.w.Write(data)
		return err
	}
	for _, c := range data {
		p.step(c)
	}
	return nil
}

func (p *jsonPrinter) step(c byte) {
	if p.inStr {
		p.tok = append(p.tok, c)
		if c == '"' {
			p.flushToken()
		}
		return
	}
	if len(p.tok) == 0 {
		if isSpace(c) {
			return
		}
		if isStruct(c) {
			p.emitStruct(c)
			return
		}
		if c == '"' {
			p.inStr = true
			p.tok = append(p.tok, c)
			return
		}
		p.tok = append(p.tok, c)
		return
	}
	if isSpace(c) || isStruct(c) || c == '"' {
		p.flushToken()
		p.step(c)
		return
	}
	p.tok = append(p.tok, c)
}

// flushToken writes out the buffered token.
func (p *jsonPrinter) flushToken() {
	if len(p.tok) == 0 {
		return
	}
	t := string(p.tok)
	if p.inStr {
		if p.colon {
			p.col(escCyan, t)
		} else {
			p.col(escBlue, t)
		}
		p.inStr = false
		p.tok = nil
		p.colon = false
		return
	}
	if p.colon {
		if t == "true" || t == "false" || t == "null" ||
			(t[0] == 't' || t[0] == 'f' || t[0] == 'n') {
			p.col(escMagenta, t)
		} else {
			p.col(escCyan, t)
		}
	} else {
		io.WriteString(p.w, t)
	}
	p.tok = nil
	p.colon = false
}

func (p *jsonPrinter) emitStruct(c byte) {
	switch c {
	case '{', '[':
		p.col(escWhite, string(c))
		p.depth++
		p.newline()
	case '}', ']':
		p.depth--
		p.newline()
		p.col(escWhite, string(c))
		if p.depth == 0 {
			p.col(escReset, "")
		}
	case ',':
		p.col(escWhite, ",")
		p.newline()
	case ':':
		p.col(escWhite, ": ")
	}
	p.colon = c == ':'
}

func (p *jsonPrinter) flush() {
	if !p.pretty {
		return
	}
	if p.inStr || len(p.tok) > 0 {
		p.flushToken()
	}
}
GOEOF
cat > filter.go <<'GOEOF'
package main

import (
	"io"
	"strings"
)

var statusRe = "HTTP/"

// respFilter copies curl's stderr to the terminal, colouring the interesting
// parts and dropping the rest.
type respFilter struct {
	w        io.Writer
	colors   bool
	verbose  bool
	echoData string

	pending  string
	havePend bool
	status   int
	buf      []byte
}

func (f *respFilter) raw(s string) { io.WriteString(f.w, s) }

func (f *respFilter) col(code, text string) {
	if f.colors {
		io.WriteString(f.w, code)
	}
	io.WriteString(f.w, text)
}

func (f *respFilter) write(data []byte) error {
	for _, c := range data {
		if c == '\n' {
			f.line(string(f.buf))
			f.buf = f.buf[:0]
			continue
		}
		f.buf = append(f.buf, c)
	}
	return nil
}

func (f *respFilter) flushLine() {
	if len(f.buf) > 0 {
		f.line(string(f.buf))
		f.buf = f.buf[:0]
	}
}

func isBlank(s string) bool { return s == "" || s == "\r" }

func isDataLine(s string) bool {
	return strings.HasPrefix(s, "{ ") || strings.HasPrefix(s, "} ")
}

// flushPending writes out a blank line that was held back while waiting to
// know whether the response was complete.
func (f *respFilter) flushPending() {
	if !f.havePend {
		return
	}
	f.raw(f.pending)
	io.WriteString(f.w, "\n")
	f.pending = ""
	f.havePend = false
}

func (f *respFilter) dropPending() {
	f.pending = ""
	f.havePend = false
}

func (f *respFilter) line(s string) {
	if isDataLine(s) {
		if f.havePend {
			f.flushPending()
			if f.verbose {
				if strings.HasPrefix(s, "} ") {
					f.raw(f.echoData)
				}
				io.WriteString(f.w, "\n")
			}
		}
		return
	}
	if strings.HasPrefix(s, "< ") {
		c := s[2:]
		if isBlank(c) {
			f.pending = c
			f.havePend = true
			return
		}
		if f.status >= 200 {
			f.flushPending()
		}
		f.emitResponseLine(c)
		return
	}
	if !f.verbose {
		if strings.HasPrefix(s, "curl: (") {
			f.flushPending()
			f.col(escRed, s)
			f.col(escReset, "")
			io.WriteString(f.w, "\n")
		}
		return
	}
	if strings.HasPrefix(s, "> ") {
		if f.status >= 200 {
			f.flushPending()
		}
		f.emitRequestLine(s[2:])
		return
	}
	if strings.HasPrefix(s, "* ") {
		if f.status >= 200 {
			f.flushPending()
		}
		f.col(escGray, s)
		f.col(escReset, "")
		io.WriteString(f.w, "\n")
		return
	}
	if strings.HasPrefix(s, "curl: (") {
		f.flushPending()
		f.col(escRed, s)
		f.col(escReset, "")
		io.WriteString(f.w, "\n")
		return
	}
	// unknown lines (progress meter, ...) are dropped
}

func (f *respFilter) emitResponseLine(c string) {
	if v, code, reason, ok := parseStatusLine(c); ok {
		f.col(escBlue, "HTTP")
		f.col(escWhite, "/")
		f.col(escCyan, v+code)
		f.col(escYellow, reason)
		f.col(escReset, "")
		io.WriteString(f.w, "\n")
		f.status = atoi(code)
		return
	}
	if i := strings.Index(c, ":"); i >= 0 {
		f.col(escWhite, c[:i+1])
		f.col(escCyan, c[i+1:])
		f.col(escReset, "")
		io.WriteString(f.w, "\n")
		return
	}
	f.raw(c)
	io.WriteString(f.w, "\n")
}

func (f *respFilter) emitRequestLine(c string) {
	if m, path, v, ok := parseRequestLine(c); ok {
		f.col(escBlue, m)
		f.col(escWhite, " "+path+" ")
		f.col(escBlue, "HTTP")
		f.col(escWhite, "/")
		f.col(escCyan, v)
		f.col(escReset, "")
		io.WriteString(f.w, "\n")
		return
	}
	if i := strings.Index(c, ":"); i >= 0 {
		f.col(escWhite, c[:i+1])
		f.col(escCyan, c[i+1:])
		f.col(escReset, "")
		io.WriteString(f.w, "\n")
		return
	}
	f.raw(c)
	io.WriteString(f.w, "\n")
}

// parseStatusLine recognises "HTTP/1.1 200 OK" style lines.
func parseStatusLine(s string) (ver, code, reason string, ok bool) {
	if !strings.HasPrefix(s, "HTTP/") {
		return "", "", "", false
	}
	rest := s[5:]
	// version: digits and dots
	i := 0
	for i < len(rest) && (rest[i] >= '0' && rest[i] <= '9' || rest[i] == '.') {
		i++
	}
	if i == 0 || i >= len(rest) || rest[i] != ' ' {
		return "", "", "", false
	}
	ver = rest[:i]
	j := i
	for j < len(rest) && rest[j] == ' ' {
		j++
	}
	k := j
	for k < len(rest) && rest[k] >= '0' && rest[k] <= '9' {
		k++
	}
	if k-j != 3 {
		return "", "", "", false
	}
	code = rest[j:k]
	if k >= len(rest) || rest[k] != ' ' {
		return "", "", "", false
	}
	reason = rest[k:]
	if reason == "" {
		return "", "", "", false
	}
	return ver, code, reason, true
}

// parseRequestLine recognises "GET /path HTTP/1.1" style lines.
func parseRequestLine(s string) (method, path, ver string, ok bool) {
	i := strings.IndexByte(s, ' ')
	if i < 0 {
		return "", "", "", false
	}
	j := strings.LastIndexByte(s, ' ')
	if j <= i {
		return "", "", "", false
	}
	rest := s[j+1:]
	if !strings.HasPrefix(rest, "HTTP/") || j+5 >= len(s) {
		return "", "", "", false
	}
	ver = rest[5:]
	if ver == "" {
		return "", "", "", false
	}
	if !isVersion(ver) {
		return "", "", "", false
	}
	return s[:i], s[i+1 : j], ver, true
}

func isVersion(s string) bool {
	dot := false
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '.' {
			dot = true
			continue
		}
		if c < '0' || c > '9' {
			return false
		}
	}
	return dot
}

func atoi(s string) int {
	n := 0
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return n
		}
		n = n*10 + int(s[i]-'0')
	}
	return n
}
GOEOF
