		f.col(escCyan, c[i+1:])
		f.col(escReset, "")
		io.WriteString(f.w, "\n")
		return
	}
	f.raw(c)
	io.WriteString(f.w, "\n")
}

func (f *respFilter) emitRequestLine(c string) {
	if m, path, v, ok := parseRequestLine(c); ok {
		f.col(escBlue, m)
		f.col(escWhite, " "+path+" ")
		f.col(escBlue, "HTTP")
		f.col(escWhite, "/")
