{"command": "cd /workspace && cat > main.go <<'GOEOF'
package main

import (
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"syscall"
	"unsafe"
)

func isATTY(f *os.File) bool {
	var t syscall.Termios
	_, _, e := syscall.Syscall(syscall.SYS_IOCTL, f.Fd(), syscall.TCGETS,
		uintptr(unsafe.Pointer(&t)))
	return e == 0
}

func main() {
	args := os.Args[1:]
	r := parse(args)
	if len(args) == 0 {
		r.helpSet = true
		r.helpCat = "all"
	}
	if r.showCmd {
		if r.urlSet {
			fmt.Fprintln(os.Stderr, displayURL(r.urlRaw))
		}
		fmt.Fprintln(os.Stdout, "curl "+renderArgs(r.buildArgs()))
		return
	}
	if r.helpSet {
		doHelp(r)
		return
	}
	runRequest(r)
}

func doHelp(r *request) {
	var cat string
	if r.helpCat != "" {
		cat = r.helpCat
	}
	path, err := lookCurl()
	if err != nil {
		fmt.Print(err)
		return
	}
	cmd := exec.Command(path, "--help", cat)
	out, err := cmd.Output()
	if err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			os.Stdout.Write(out)
			os.Exit(ee.ExitCode())
		}
		fmt.Print(err)
		return
	}
	fmt.Printf("Usage: %s [options...] [METHOD] URL [REQUEST_ITEM [REQUEST_ITEM ...]]\n", os.Args[0])
	lines := strings.Split(string(out), "\n")
	if len(lines) > 1 {
		io.WriteString(os.Stdout, strings.Join(lines[1:], "\n"))
	}
	os.Exit(0)
}

func lookCurl() (string, error) {
	p, err := exec.LookPath("curl")
	if err != nil {
		return "", err
	}
	return p, nil
}

// runRequest performs the request, streaming the output through the
// pretty-printer / header filter when appropriate.
func runRequest(r *request) {
	curlArgs := r.buildArgs()
	if r.urlSet {
		fmt.Fprintln(os.Stderr, displayURL(r.urlRaw))
	}
	pretty := r.pretty || isATTY(os.Stdout)
	verbose := r.verbose || isATTY(os.Stderr)
	if !pretty && !verbose {
		p, err := lookCurl()
		if err != nil {
			fmt.Print(err)
			return
		}
		argv := append([]string{os.Args[0]}, curlArgs...)
		env := os.Environ()
		if err := syscall.Exec(p, argv, env); err != nil {
			fmt.Print(err)
			return
		}
		return
	}
	p, err := lookCurl()
	if err != nil {
		fmt.Print(err)
		return
	}
	filteredRun(p, curlArgs, r, pretty, verbose)
}

// filteredRun starts curl as a child process, copies its stdout through the
// JSON pretty printer and its stderr through the response header filter.
func filteredRun(path string, args []string, r *request, pretty, verbose bool) {
	cmd := exec.Command(path, args...)
	cmd.Stdin = os.Stdin
	outR, outW, err := os.Pipe()
	if err != nil {
		fmt.Print(err)
		return
	}
	errR, errW, err := os.Pipe()
	if err != nil {
		fmt.Print(err)
		return
	}
	cmd.Stdout = outW
	cmd.Stderr = errW
	if err := cmd.Start(); err != nil {
		fmt.Print(err)
		return
	}
	outW.Close()
	errW.Close()

	body, _ := r.dataJSON()
	done := make(chan struct{}, 2)
	go func() {
		jp := &jsonPrinter{w: os.Stdout, colors: pretty || verbose}
		buf := make([]byte, 32*1024)
		for {
			n, err := outR.Read(buf)
			if n > 0 {
				jp.write(buf[:n])
			}
			if err != nil {
				break
			}
		}
		jp.flush()
		outR.Close()
		done <- struct{}{}
	}()
	go func() {
		f := &respFilter{w: os.Stderr, colors: pretty || verbose, verbose: r.verbose, echoData: body}
		buf := make([]byte, 32*1024)
		for {
			n, err := errR.Read(buf)
			if n > 0 {
				f.write(buf[:n])
			}
			if err != nil {
				break
			}
		}
		f.flushLine()
		errR.Close()
		done <- struct{}{}
	}()
	<-done
	<-done
	cmd.Wait()
	os.Exit(cmd.ProcessState.ExitCode())
}
GOEOF
