s=open('request.go').read()
old = s[s.index('// buildArgs produces'):]
new = '''// buildArgs produces the argument list that is passed on to curl.
func (r *request) buildArgs() []string {
	var out []string
	out = append(out, r.args...)
	switch {
	case r.method == "":
	case r.method == "HEAD":
		out = append(out, "-I")
	default:
		out = append(out, "-X", r.method)
	}
	for _, it := range r.items {
		if it.header {
			out = append(out, "-H", it.val)
		} else {
			out = append(out, it.val)
		}
	}
	if body, ok := r.dataJSON(); ok {
		out = append(out, "-d", body)
	}
	u := r.url
	if s := r.querySuffix(); s != "" {
		if strings.Contains(u, "?") {
			u += "&" + s
		} else {
			u += "?" + s
		}
	}
	out = append(out, u)
	out = append(out, "-s", "-S")
	if isATTY(os.Stderr) {
		out = append(out, "-v")
	}
	if !r.dataSet && !isATTY(os.Stdin) {
		out = append(out, "-d@-")
	}
	if _, ok := r.dataJSON(); ok || r.dataSet || !isATTY(os.Stdin) {
		if !r.hasCT {
			out = append(out, "-H", "Content-Type: application/json")
		}
	}
	if !r.hasAcc {
		out = append(out, "-H", "Accept: application/json, */*")
	}
	return out
}

